func (this *Io_WKTReaderTest) extractCS_Geometry(geom *Geom_Geometry) Geom_CoordinateSequence {
	if Geom_Point_isKind((*Geom_Geometry)(unsafe.Pointer(geom))) {
		return (Geom_Point_downcast((*Geom_Geometry)(unsafe.Pointer(geom)))).GetCoordinateSequence()
	}
	if Geom_LineString_isKind((*Geom_Geometry)(unsafe.Pointer(geom))) {
		return (Geom_LineString_downcast((*Geom_Geometry)(unsafe.Pointer(geom)))).GetCoordinateSequence()
	}
	panic(java.Ref(java.IllegalArgumentException_new_String(java.Concat(jlit_2301, geom.GetGeometryType()))))
}
